	}
}

package main

import (
	"context"
	"fmt"
)

func main() {
	parent, stop := context.WithCancel(context.Background())
	defer stop()
	child, cancel := context.WithCancel(parent)
	cancel()
	if parent.Err() == nil {
		fmt.Println(1)
	} else {
		fmt.Println(0)
	}
	if child.Err() == context.Canceled {
		fmt.Println(2)
	} else {
		fmt.Println(0)
	}
}

