	"fmt"
)

func main() {
	p, cancel := context.WithCancel(context.Background())
	c1, s1 := context.WithCancel(p)
	c2, s2 := context.WithCancel(p)
	defer s1()
	defer s2()
	cancel()
	n := 0
	if c1.Err() != nil {
		n++
	}
	if c2.Err() != nil {
		n++
	}
	fmt.Println(n)
}

